export const tarjetas = [

  // === FASE 3-1: ¿Qué es Express.js? ===
  {
    fase: 3, titulo: "¿Qué es Express.js?", menuTitulo: "¿Qué es Express?",
    capas: [
      { nombre: "El problema de node:http", contenido: `<p class="mb-6">Ya viste cómo crear un servidor con <code>node:http</code>. Funciona, pero es de <strong>muy bajo nivel</strong>: solo abre un canal de red y analiza texto crudo de HTTP. Todo lo demás lo tienes que programar tú.</p><p class="mb-6"><strong>Express.js</strong> es una librería que se monta sobre <code>node:http</code> y te da herramientas listas para no reinventar la rueda. Toca cada problema para ver la diferencia:</p><div style="display:flex;flex-direction:column;gap:0.5rem;max-width:30rem;margin:0 auto;" id="express-problemas"><div class="cap-item" data-cap="e0" onclick="revelarExpress(0)"><span class="cap-icono">?</span><span class="cap-texto">Gestionar rutas (/usuarios, /productos...)</span></div><div class="cap-item" data-cap="e1" onclick="revelarExpress(1)"><span class="cap-icono">?</span><span class="cap-texto">Leer datos que envía el cliente (JSON, formularios)</span></div><div class="cap-item" data-cap="e2" onclick="revelarExpress(2)"><span class="cap-icono">?</span><span class="cap-texto">Enviar respuestas con formato correcto</span></div><div class="cap-item" data-cap="e3" onclick="revelarExpress(3)"><span class="cap-icono">?</span><span class="cap-texto">Ejecutar lógica común para todas las rutas</span></div></div><div id="express-detalle" class="mt-4" style="max-width:30rem;margin-left:auto;margin-right:auto;min-height:3rem;"></div>` },
      { nombre: "Cómo se instala", contenido: `<p class="mb-6">Express no viene con Node.js: es una librería externa que se instala con el gestor de paquetes.</p><pre class="bloque-codigo"><code><span class="code-comment">// Instalar Express en tu proyecto</span>\n<span class="code-method">pnpm add</span> <span class="code-string">express</span></code></pre><p class="mt-6">Al ejecutar ese comando, pasan dos cosas automáticamente:</p><table class="mt-2"><thead><tr><th>Qué pasa</th><th>Dónde</th></tr></thead><tbody><tr><td>Se descarga el código de Express</td><td><code>node_modules/express/</code></td></tr><tr><td>Se registra como dependencia</td><td><code>package.json → dependencies</code></td></tr></tbody></table>` },
      { nombre: "Ponlo a prueba", contenido: `<div style="display:flex;flex-direction:column;gap:1.25rem;padding-bottom:0;"><div><p class="ejercicio-pregunta" style="text-align:center;">Express reemplaza por completo a node:http; una vez que usas Express, node:http deja de estar involucrado en tu servidor.</p><div style="display:flex;justify-content:center;gap:1rem;margin-top:0.75rem;"><button id="vf-btn-v-1" class="motor-btn simbolo-inactivo" style="min-width:8rem;" onclick="responderVF('verdadero','falso','Express se monta sobre node:http, no lo reemplaza. Cuando ejecutas app.listen(), Express llama a http.createServer() por ti, detrás de escena.','Exacto: Express se monta sobre node:http, no lo reemplaza. Cuando ejecutas app.listen(), Express llama a http.createServer() por ti, detrás de escena.','1')">Verdadero</button><button id="vf-btn-f-1" class="motor-btn simbolo-inactivo" style="min-width:8rem;" onclick="responderVF('falso','falso','Express se monta sobre node:http, no lo reemplaza. Cuando ejecutas app.listen(), Express llama a http.createServer() por ti, detrás de escena.','Exacto: Express se monta sobre node:http, no lo reemplaza. Cuando ejecutas app.listen(), Express llama a http.createServer() por ti, detrás de escena.','1')">Falso</button></div><div id="vf-retro-1" class="mt-4" style="min-height:3rem;"></div></div><div><p class="ejercicio-pregunta" style="text-align:center;">Express viene incluido en Node.js: no hace falta instalarlo por separado.</p><div style="display:flex;justify-content:center;gap:1rem;margin-top:0.75rem;"><button id="vf-btn-v-2" class="motor-btn simbolo-inactivo" style="min-width:8rem;" onclick="responderVF('verdadero','falso','Express es una librería externa, no un módulo nativo de Node. Hay que instalarla con el gestor de paquetes (pnpm add express).','Exacto: Express es una librería externa, no un módulo nativo de Node. Hay que instalarla con pnpm add express.','2')">Verdadero</button><button id="vf-btn-f-2" class="motor-btn simbolo-inactivo" style="min-width:8rem;" onclick="responderVF('falso','falso','Express es una librería externa, no un módulo nativo de Node. Hay que instalarla con el gestor de paquetes (pnpm add express).','Exacto: Express es una librería externa, no un módulo nativo de Node. Hay que instalarla con pnpm add express.','2')">Falso</button></div><div id="vf-retro-2" class="mt-4" style="min-height:3rem;"></div></div><div><p class="ejercicio-pregunta" style="text-align:center;">Al instalar Express con pnpm add express, la librería se registra automáticamente en el objeto dependencies de package.json.</p><div style="display:flex;justify-content:center;gap:1rem;margin-top:0.75rem;"><button id="vf-btn-v-3" class="motor-btn simbolo-inactivo" style="min-width:8rem;" onclick="responderVF('verdadero','verdadero','Exacto: pnpm add hace dos cosas a la vez: descarga el código en node_modules y registra la dependencia en package.json.','Exacto: pnpm add hace dos cosas a la vez: descarga el código en node_modules y registra la dependencia en package.json.','3')">Verdadero</button><button id="vf-btn-f-3" class="motor-btn simbolo-inactivo" style="min-width:8rem;" onclick="responderVF('falso','verdadero','Exacto: pnpm add hace dos cosas a la vez: descarga el código en node_modules y registra la dependencia en package.json.','Exacto: pnpm add hace dos cosas a la vez: descarga el código en node_modules y registra la dependencia en package.json.','3')">Falso</button></div><div id="vf-retro-3" class="mt-4" style="min-height:3rem;"></div></div></div>` },
    ],
    ejercicio: { tipo: "opcion_multiple", pregunta: "¿Qué relación tiene Express con node:http?", opciones: ["Express reemplaza node:http completamente", "Express se monta sobre node:http y lo simplifica", "Son dos cosas independientes", "Express es un módulo nativo de Node"], respuestaCorrecta: 1, retroalimentacion: { correcta: "Exacto: Express usa node:http internamente. Cuando haces app.listen(), Express ejecuta http.createServer() por ti detrás de escena.", incorrecta: "Express no reemplaza node:http ni es independiente. Piensa: ¿qué hace Express cuando arrancas el servidor con app.listen()?" } }
  },

  // === FASE 3-2: Tu primer servidor con Express ===
  {
    fase: 3, titulo: "Tu primer servidor con Express", menuTitulo: "Servidor Express",
    capas: [
      { nombre: "El código completo", contenido: `<pre class="bloque-codigo"><code><span class="code-comment">// 1. Importamos Express (librería instalada con pnpm add)</span>\n<span class="code-keyword">import</span> express <span class="code-keyword">from</span> <span class="code-string">'express'</span>;\n\n<span class="code-comment">// 2. Creamos la aplicación</span>\n<span class="code-comment">//    express() devuelve un objeto con toda la funcionalidad</span>\n<span class="code-keyword">const</span> app = <span class="code-method">express</span>();\n\n<span class="code-comment">// 3. Definimos una ruta: cuando alguien visite "/", responder</span>\napp.<span class="code-method">get</span>(<span class="code-string">'/'</span>, (req, res) => {\n  res.<span class="code-method">send</span>(<span class="code-string">'Servidor Express activo'</span>);\n});\n\n<span class="code-comment">// 4. Arrancamos el servidor en el puerto 3000</span>\napp.<span class="code-method">listen</span>(<span class="code-number">3000</span>, () => {\n  console.<span class="code-method">log</span>(<span class="code-string">'Servidor en http://localhost:3000'</span>);\n});</code></pre>` },
      { nombre: "node:http vs Express", contenido: `<p class="mb-6">El mismo servidor, en ambas versiones. Toca para comparar:</p><div style="display:flex;justify-content:center;gap:1rem;margin-bottom:1rem;"><button id="btn-nativo" class="motor-btn simbolo-inactivo" onclick="compararServidor('nativo')">node:http</button><button id="btn-express" class="motor-btn simbolo-inactivo" onclick="compararServidor('express')">Express</button></div><pre class="bloque-codigo"><code id="comparar-codigo" style="min-height:8rem;"><span class="code-comment">// Elige una opción arriba</span></code></pre>` },
      { nombre: "Las piezas nuevas", contenido: `<table><thead><tr><th>Express</th><th>Qué hace</th><th>Equivalente en node:http</th></tr></thead><tbody><tr><td><code>express()</code></td><td>Crea la aplicación con toda la funcionalidad de Express</td><td><code>http.createServer()</code></td></tr><tr><td><code>app.get(ruta, fn)</code></td><td>Define qué hacer cuando llega un GET a esa ruta</td><td><code>if (req.url === '/' && req.method === 'GET')</code></td></tr><tr><td><code>res.send()</code></td><td>Envía respuesta, fija headers y cierra conexión automáticamente</td><td><code>res.setHeader() + res.end()</code></td></tr><tr><td><code>app.listen()</code></td><td>Arranca el servidor (llama a http.createServer internamente)</td><td><code>server.listen()</code></td></tr></tbody></table><div class="recuadro-resaltado mt-4">Express no reemplaza node:http: lo envuelve. Cuando escribes <code>app.listen()</code>, Express ejecuta <code>http.createServer(app)</code> internamente.</div>` },
      { nombre: "Completa el código", contenido: `<p class="ejercicio-pregunta mb-2" style="text-align:center;">Quieres definir qué debe pasar cuando alguien visita la ruta "/" con una petición GET.</p><p class="mb-8" style="text-align:center;font-size:0.85rem;opacity:0.7;">Elige la ficha correcta para completar el espacio en blanco:</p><pre class="bloque-codigo"><code><span class="code-keyword">import</span> express <span class="code-keyword">from</span> <span class="code-string">'express'</span>;\n\n<span class="code-keyword">const</span> app = <span class="code-method">express</span>();\n\napp.<span id="cc-express-blanco" class="cc-blanco" data-contenedor="express"></span>(<span class="code-string">'/'</span>, (req, res) => {\n  res.<span class="code-method">send</span>(<span class="code-string">'Servidor Express activo'</span>);\n});\n\napp.<span class="code-method">listen</span>(<span class="code-number">3000</span>);</code></pre><div style="display:flex;justify-content:center;gap:0.75rem;margin-top:1.5rem;flex-wrap:wrap;"><button class="cc-ficha" data-contenedor="express" data-valor="get" data-correcta="true" data-retro="Exacto: app.get() define qué hacer cuando llega una petición GET a esa ruta." onclick="completarClick(this)">get</button><button class="cc-ficha" data-contenedor="express" data-valor="send" data-correcta="false" data-retro="send() existe, pero se usa en res.send(), para enviar la respuesta, no para definir una ruta." onclick="completarClick(this)">send</button><button class="cc-ficha" data-contenedor="express" data-valor="use" data-correcta="false" data-retro="app.use() existe, pero se usa para middlewares generales, no específicamente para responder a un método GET." onclick="completarClick(this)">use</button><button class="cc-ficha" data-contenedor="express" data-valor="create" data-correcta="false" data-retro="create no es un método de Express que se use aquí para definir rutas." onclick="completarClick(this)">create</button></div><div id="cc-express-retro" class="mt-6" style="min-height:3rem;"></div>` },
    ],
    ejercicio: { tipo: "opcion_multiple", pregunta: "¿Cuál es la diferencia principal entre res.send() de Express y res.end() de node:http?", opciones: ["No hay diferencia, hacen lo mismo", "res.send() fija el Content-Type y el Content-Length automáticamente", "res.send() solo sirve para JSON", "res.end() es más rápido"], respuestaCorrecta: 1, retroalimentacion: { correcta: "Exacto: res.send() detecta el tipo de dato que le pasas, fija las cabeceras apropiadas y cierra la conexión. Con res.end() tienes que hacer todo eso a mano.", incorrecta: "Piensa en lo que tenías que hacer manualmente con node:http (setHeader, statusCode, end). ¿Cuántos de esos pasos hace res.send() por ti?" } }
  },

  // === FASE 3-3: Rutas y parámetros ===
  {
    fase: 3, titulo: "Rutas y parámetros", menuTitulo: "Rutas y parámetros",
    capas: [
      { nombre: "Definir rutas", contenido: `<p class="mb-6">Cada ruta combina un <strong>método HTTP</strong> (qué quiero hacer) con una <strong>URL</strong> (dónde). Express ejecuta la función solo si coinciden ambos:</p><pre class="bloque-codigo"><code><span class="code-comment">// Solo se ejecuta si el cliente envía GET a /productos</span>\napp.<span class="code-method">get</span>(<span class="code-string">'/productos'</span>, (req, res) => {\n  res.<span class="code-method">send</span>(<span class="code-string">'Lista de productos'</span>);\n});\n\n<span class="code-comment">// Solo se ejecuta si el cliente envía POST a /productos</span>\napp.<span class="code-method">post</span>(<span class="code-string">'/productos'</span>, (req, res) => {\n  res.<span class="code-method">send</span>(<span class="code-string">'Producto creado'</span>);\n});</code></pre><div class="recuadro-resaltado mt-4">La misma URL (<code>/productos</code>) puede tener funciones diferentes según el verbo. Eso es lo que aprendiste como <strong>enrutamiento semántico</strong> en la Fase 4.</div>` },
      { nombre: "params vs query", contenido: `<p class="mb-6">Hay dos formas de enviar datos en la URL. Toca cada una para comparar:</p><div style="display:flex;justify-content:center;gap:1rem;margin-bottom:1rem;"><button id="btn-params" class="motor-btn simbolo-inactivo" onclick="compararParams('params')">req.params</button><button id="btn-query" class="motor-btn simbolo-inactivo" onclick="compararParams('query')">req.query</button></div><pre class="bloque-codigo"><code id="params-codigo" style="min-height:6rem;"><span class="code-comment">// Elige una opción arriba</span></code></pre><div class="consola-simulada mt-3"><div class="consola-header">Resultado</div><pre id="params-resultado" style="margin:0;background:transparent;padding:0;font-size:inherit;line-height:inherit;"><span style="opacity:0.4;">Esperando...</span></pre></div>` },
      { nombre: "Cuándo usar cada uno", contenido: `<table><thead><tr><th></th><th>req.params</th><th>req.query</th></tr></thead><tbody><tr><td>Para qué</td><td>Identificar <strong>un</strong> recurso específico</td><td>Filtrar, ordenar o paginar</td></tr><tr><td>¿Obligatorio?</td><td>Sí (si falta, la ruta no coincide)</td><td>No (es opcional)</td></tr><tr><td>En la URL</td><td><code>/productos/<strong>45</strong></code></td><td><code>/productos?<strong>color=rojo</strong></code></td></tr><tr><td>En Express</td><td><code>app.get('/productos/:id')</code></td><td><code>app.get('/productos')</code></td></tr><tr><td>Se lee con</td><td><code>req.params.id</code></td><td><code>req.query.color</code></td></tr></tbody></table>` },
      { nombre: "Une cada característica", contenido: `<p class="mb-8" style="text-align:center;">Toca un elemento y después a cuál pertenece, en la columna derecha. Si te equivocas, podrás volver a intentarlo.</p><div style="position:relative;"><svg id="pareados-params-svg" style="position:absolute;top:0;left:0;width:100%;height:100%;pointer-events:none;"></svg><div style="display:grid;grid-template-columns:max-content max-content;gap:1.25rem 12rem;position:relative;z-index:1;width:fit-content;margin:0 auto;align-items:stretch;"><button class="pareado-item pareado-izq" data-contenedor="params" data-lado="izq" data-par="params" onclick="pareadoClick(this)"><span><code>req.params</code></span></button><button class="pareado-item pareado-der" data-contenedor="params" data-lado="der" data-par="query" onclick="pareadoClick(this)"><span>Sirve para filtrar, ordenar o paginar, y siempre es opcional</span></button><button class="pareado-item pareado-izq" data-contenedor="params" data-lado="izq" data-par="query" onclick="pareadoClick(this)"><span><code>req.query</code></span></button><button class="pareado-item pareado-der" data-contenedor="params" data-lado="der" data-par="dospuntos" onclick="pareadoClick(this)"><span>Se define con dos puntos antes del nombre, dentro de la ruta</span></button><button class="pareado-item pareado-izq" data-contenedor="params" data-lado="izq" data-par="dospuntos" onclick="pareadoClick(this)"><span><code>:id</code></span></button><button class="pareado-item pareado-der" data-contenedor="params" data-lado="der" data-par="interrogacion" onclick="pareadoClick(this)"><span>Aparece después del signo de interrogación en la URL</span></button><button class="pareado-item pareado-izq" data-contenedor="params" data-lado="izq" data-par="interrogacion" onclick="pareadoClick(this)"><span><code>?color=rojo</code></span></button><button class="pareado-item pareado-der" data-contenedor="params" data-lado="der" data-par="params" onclick="pareadoClick(this)"><span>Identifica un recurso específico; si falta, la ruta ni siquiera coincide</span></button></div></div><div id="pareados-params-retro" class="mt-6" style="min-height:3rem;"></div>` },
    ],
    ejercicio: { tipo: "opcion_multiple", pregunta: "Tienes la ruta app.get('/usuarios/:id'). Un cliente visita /usuarios/88. ¿Qué valor tiene req.params.id?", opciones: ["undefined", "':id'", "'88'", "88 (número)"], respuestaCorrecta: 2, retroalimentacion: { correcta: "Exacto: Express captura el valor '88' como string y lo guarda en req.params.id.", incorrecta: "Los :id en la ruta son variables. Express toma lo que el cliente puso en esa posición de la URL y lo guarda como string en req.params." } }
  },

  // === FASE 3-4: Middlewares ===
  {
    fase: 3, titulo: "Middlewares", menuTitulo: "Middlewares",
    capas: [
      { nombre: "¿Qué es un middleware?", contenido: `<p class="mb-6">Un <strong>middleware</strong> es una función que se ejecuta <strong>entre</strong> que la petición llega al servidor y que la respuesta sale. Tiene acceso a <code>req</code>, <code>res</code> y a una función especial llamada <code>next()</code>.</p><pre class="bloque-codigo"><code><span class="code-comment">// Un middleware básico: registra cada petición que llega</span>\napp.<span class="code-method">use</span>((req, res, next) => {\n  console.<span class="code-method">log</span>(<span class="code-string">'Petición recibida:'</span>, req.method, req.url);\n  <span class="code-method">next</span>();  <span class="code-comment">// pasa al siguiente middleware o ruta</span>\n});</code></pre><table class="mt-4"><thead><tr><th>Pieza</th><th>Qué hace</th></tr></thead><tbody><tr><td><code>app.use(fn)</code></td><td>Registra el middleware para <strong>todas</strong> las rutas y métodos</td></tr><tr><td><code>next()</code></td><td>Le dice a Express: "ya terminé, pasa al siguiente"</td></tr></tbody></table>` },
      { nombre: "La cadena", contenido: `<p class="mb-6">Los middlewares se ejecutan en el orden en que los escribiste. Toca cada paso para ver el flujo:</p><div style="display:flex;flex-direction:column;gap:0.5rem;max-width:30rem;margin:0 auto;"><div class="flujo-paso flujo-activo" onclick="avanzarCadena(0)"><span class="flujo-num">1</span><div><strong>express.json()</strong><br><span style="font-size:0.8rem;opacity:0.7;">Convierte los bytes del body en un objeto JS → req.body</span></div></div><div class="flujo-paso flujo-pendiente" onclick="avanzarCadena(1)"><span class="flujo-num">2</span><div><strong>Tu middleware de log</strong><br><span style="font-size:0.8rem;opacity:0.7;">Imprime "Petición recibida: GET /usuarios" → next()</span></div></div><div class="flujo-paso flujo-pendiente" onclick="avanzarCadena(2)"><span class="flujo-num">3</span><div><strong>app.get('/usuarios', fn)</strong><br><span style="font-size:0.8rem;opacity:0.7;">La ruta coincide → ejecuta la función y envía res.json()</span></div></div></div><div class="recuadro-resaltado mt-6">Si un middleware no llama a <code>next()</code> y no envía respuesta, la petición se queda <strong>colgada</strong>: el navegador esperará hasta que la conexión expire.</div>` },
      { nombre: "Middleware vs ruta", contenido: `<table><thead><tr><th></th><th>Middleware</th><th>Ruta</th></tr></thead><tbody><tr><td>Propósito</td><td>Preparar, validar, registrar</td><td>Responder al cliente</td></tr><tr><td>¿Llama next()?</td><td>Sí (pasa al siguiente)</td><td>No (es el destino final)</td></tr><tr><td>¿Envía respuesta?</td><td>Normalmente no</td><td>Sí (res.send, res.json...)</td></tr><tr><td>¿Para qué rutas?</td><td>Todas (con app.use)</td><td>Una específica (app.get('/ruta'))</td></tr></tbody></table><pre class="bloque-codigo mt-4"><code><span class="code-comment">// Middleware: prepara (no responde, llama next)</span>\napp.<span class="code-method">use</span>(express.<span class="code-method">json</span>());\n\n<span class="code-comment">// Ruta: responde (no llama next)</span>\napp.<span class="code-method">get</span>(<span class="code-string">'/usuarios'</span>, (req, res) => {\n  res.<span class="code-method">json</span>(usuarios);\n});</code></pre>` },
      { nombre: "Ordena la cadena", contenido: `<p class="ejercicio-pregunta mb-2" style="text-align:center;">Pon estos 4 momentos de una petición POST en Express en el orden en que realmente ocurren.</p><p class="mb-8" style="text-align:center;font-size:0.85rem;opacity:0.7;">Arrastra los pasos hasta dejarlos en el orden correcto y presiona "Comprobar respuesta":</p><div class="ordena-lista" data-contenedor="middleware" data-orden-correcto="llega,json,log,ruta" ondragover="ordenaDragOver(event)"><div class="ordena-item" draggable="true" data-paso="ruta" ondragstart="ordenaDragStart(event)" ondragend="ordenaDragEnd(event)"><span class="ordena-handle"><svg width="10" height="16" viewBox="0 0 10 16"><circle cx="2" cy="2" r="1.5" fill="currentColor"/><circle cx="8" cy="2" r="1.5" fill="currentColor"/><circle cx="2" cy="8" r="1.5" fill="currentColor"/><circle cx="8" cy="8" r="1.5" fill="currentColor"/><circle cx="2" cy="14" r="1.5" fill="currentColor"/><circle cx="8" cy="14" r="1.5" fill="currentColor"/></svg></span><span>La ruta responde con res.json()</span></div><div class="ordena-item" draggable="true" data-paso="llega" ondragstart="ordenaDragStart(event)" ondragend="ordenaDragEnd(event)"><span class="ordena-handle"><svg width="10" height="16" viewBox="0 0 10 16"><circle cx="2" cy="2" r="1.5" fill="currentColor"/><circle cx="8" cy="2" r="1.5" fill="currentColor"/><circle cx="2" cy="8" r="1.5" fill="currentColor"/><circle cx="8" cy="8" r="1.5" fill="currentColor"/><circle cx="2" cy="14" r="1.5" fill="currentColor"/><circle cx="8" cy="14" r="1.5" fill="currentColor"/></svg></span><span>La petición POST llega al servidor</span></div><div class="ordena-item" draggable="true" data-paso="json" ondragstart="ordenaDragStart(event)" ondragend="ordenaDragEnd(event)"><span class="ordena-handle"><svg width="10" height="16" viewBox="0 0 10 16"><circle cx="2" cy="2" r="1.5" fill="currentColor"/><circle cx="8" cy="2" r="1.5" fill="currentColor"/><circle cx="2" cy="8" r="1.5" fill="currentColor"/><circle cx="8" cy="8" r="1.5" fill="currentColor"/><circle cx="2" cy="14" r="1.5" fill="currentColor"/><circle cx="8" cy="14" r="1.5" fill="currentColor"/></svg></span><span>express.json() convierte el body en objeto</span></div><div class="ordena-item" draggable="true" data-paso="log" ondragstart="ordenaDragStart(event)" ondragend="ordenaDragEnd(event)"><span class="ordena-handle"><svg width="10" height="16" viewBox="0 0 10 16"><circle cx="2" cy="2" r="1.5" fill="currentColor"/><circle cx="8" cy="2" r="1.5" fill="currentColor"/><circle cx="2" cy="8" r="1.5" fill="currentColor"/><circle cx="8" cy="8" r="1.5" fill="currentColor"/><circle cx="2" cy="14" r="1.5" fill="currentColor"/><circle cx="8" cy="14" r="1.5" fill="currentColor"/></svg></span><span>Tu middleware registra la petición en consola</span></div></div><div style="text-align:center;margin-top:1.5rem;"><button class="motor-btn" onclick="comprobarOrden('middleware')">Comprobar respuesta</button></div><div id="ordena-middleware-retro" class="mt-4" style="min-height:3rem;"></div>` },
    ],
    ejercicio: { tipo: "opcion_multiple", pregunta: "¿Qué pasa si un middleware no llama a next() y no envía respuesta?", opciones: ["Express llama a next() automáticamente", "Se ejecuta la siguiente ruta de todos modos", "La petición se queda colgada indefinidamente", "El servidor se reinicia"], respuestaCorrecta: 2, retroalimentacion: { correcta: "Exacto: Express no sabe que el middleware terminó. Sin next() ni respuesta, el cliente se queda esperando hasta que la conexión expire por timeout.", incorrecta: "Express no asume nada: necesita que tú explícitamente llames next() o envíes una respuesta. Si no haces ninguna de las dos, ¿qué le pasa al cliente?" } }
  },

  // === FASE 3-5: Motor de plantillas EJS ===
  {
    fase: 3, titulo: "Motor de plantillas EJS", menuTitulo: "EJS",
    capas: [
      { nombre: "¿Qué es EJS?", contenido: `<p class="mb-6"><strong>EJS</strong> (<em>Embedded JavaScript</em>) es un motor de plantillas: una herramienta que permite generar HTML dinámico en el servidor, fusionando HTML estático con datos de JavaScript.</p><pre class="bloque-codigo"><code><span class="code-comment">// 1. Configurar EJS en Express</span>\napp.<span class="code-method">set</span>(<span class="code-string">'view engine'</span>, <span class="code-string">'ejs'</span>);\n\n<span class="code-comment">// 2. En la ruta, renderizar una vista pasándole datos</span>\napp.<span class="code-method">get</span>(<span class="code-string">'/usuario'</span>, (req, res) => {\n  res.<span class="code-method">render</span>(<span class="code-string">'perfil'</span>, { nombre: <span class="code-string">'Carlos'</span> });\n});\n\n<span class="code-comment">// Express busca el archivo views/perfil.ejs</span>\n<span class="code-comment">// Le pasa { nombre: 'Carlos' } como datos</span>\n<span class="code-comment">// EJS genera el HTML final y lo envía al navegador</span></code></pre>` },
      { nombre: "Las etiquetas de EJS", contenido: `<p class="mb-6">EJS usa etiquetas especiales para insertar JavaScript dentro del HTML. Toca cada tipo:</p><div style="display:flex;justify-content:center;gap:1rem;margin-bottom:1rem;"><button id="btn-ejs-salida" class="motor-btn simbolo-inactivo" onclick="mostrarEjs('salida')"><%= %> Salida</button><button id="btn-ejs-control" class="motor-btn simbolo-inactivo" onclick="mostrarEjs('control')"><% %> Control</button></div><div id="ejs-ejemplo" style="max-width:30rem;margin:0 auto;min-height:6rem;"></div>` },
      { nombre: "Encuentra el error", contenido: `<div class="ee-wrap" data-contenedor="ejs"><p class="ejercicio-pregunta mb-2" style="text-align:center;">Esta plantilla EJS no funciona.</p><p class="mb-4" style="text-align:center;font-size:0.85rem;opacity:0.7;">Toca la línea que tiene un error:</p><pre class="bloque-codigo"><code><div class="ee-linea" data-contenedor="ejs" data-error="false" onclick="eeClick(this)"><span class="code-string">&lt;h1&gt;</span>Perfil de usuario<span class="code-string">&lt;/h1&gt;</span></div><div class="ee-linea" data-contenedor="ejs" data-error="false" onclick="eeClick(this)"></div><div class="ee-linea" data-contenedor="ejs" data-error="true" data-retro="Exacto: la etiqueta de salida (<%= %>) espera un valor para imprimir, no una instrucción de control como if. Un if no devuelve nada, por eso rompe la plantilla. Debería ser una etiqueta de control (<% %>), sin el signo =." onclick="eeClick(this)">&lt;%= <span class="code-keyword">if</span> (nombre) { %&gt;</div><div class="ee-linea" data-contenedor="ejs" data-error="false" data-pista="Esa línea es correcta: usa la etiqueta de salida (con =) para imprimir un valor, que es justo lo que corresponde." onclick="eeClick(this)">  <span class="code-string">&lt;p&gt;</span>Hola, &lt;%= nombre %&gt;<span class="code-string">&lt;/p&gt;</span></div><div class="ee-linea" data-contenedor="ejs" data-error="false" data-pista="Esa línea es correcta: cierra el bloque de control sin usar el signo =, tal como corresponde." onclick="eeClick(this)">&lt;% } %&gt;</div></code></pre><div id="ee-ejs-retro" class="mt-4" style="min-height:3rem;"></div></div>` },
    ],
    ejercicio: { tipo: "opcion_multiple", pregunta: "¿Qué diferencia hay entre <%= nombre %> y <% nombre %> en EJS?", opciones: ["No hay diferencia", "<%= %> imprime el valor en el HTML, <% %> ejecuta lógica sin imprimir", "<% %> imprime y <%= %> ejecuta", "<%= %> es para strings y <% %> para números"], respuestaCorrecta: 1, retroalimentacion: { correcta: "Exacto: el signo = hace que el valor se inserte visiblemente en el HTML. Sin él, el código se ejecuta pero no se muestra (útil para if, for, etc.).", incorrecta: "Piensa en el = como 'imprimir'. Con = se ve en la página. Sin = se ejecuta en silencio (para lógica como if o for)." } }
  },

  // === FASE 3-6: Manejo de errores ===
  {
    fase: 3, titulo: "Manejo de errores en Express", menuTitulo: "Manejo de errores",
    capas: [
      { nombre: "El middleware de error", contenido: `<p class="mb-6">Express tiene un tipo especial de middleware para errores. Lo diferencia porque recibe <strong>4 parámetros</strong> en vez de 3:</p><pre class="bloque-codigo"><code><span class="code-comment">// Middleware normal: 3 parámetros</span>\napp.<span class="code-method">use</span>((req, res, next) => { ... });\n\n<span class="code-comment">// Middleware de ERROR: 4 parámetros</span>\n<span class="code-comment">// Express sabe que es de error por el número de argumentos</span>\napp.<span class="code-method">use</span>((err, req, res, next) => {\n  console.<span class="code-method">error</span>(err.message);\n  res.<span class="code-method">status</span>(<span class="code-number">500</span>).<span class="code-method">json</span>({ error: <span class="code-string">'Error interno del servidor'</span> });\n});</code></pre><div class="recuadro-resaltado mt-4">Este middleware debe ir al <strong>final del archivo</strong>, después de todas las rutas. Si lo pones antes, no capturará errores de las rutas que vengan después.</div>` },
      { nombre: "El orden importa", contenido: `<p class="mb-6">Express procesa todo de arriba hacia abajo. Toca cada paso para ver el orden correcto:</p><div style="display:flex;flex-direction:column;gap:0.5rem;max-width:30rem;margin:0 auto;"><div class="flujo-paso flujo-activo" onclick="avanzarOrdenError(0)"><span class="flujo-num">1</span><div><strong>Middlewares globales</strong><br><span style="font-size:0.8rem;opacity:0.7;">express.json(), cors(), logs...</span></div></div><div class="flujo-paso flujo-pendiente" onclick="avanzarOrdenError(1)"><span class="flujo-num">2</span><div><strong>Rutas normales</strong><br><span style="font-size:0.8rem;opacity:0.7;">app.get(), app.post(), etc.</span></div></div><div class="flujo-paso flujo-pendiente" onclick="avanzarOrdenError(2)"><span class="flujo-num">3</span><div><strong>Middleware 404</strong><br><span style="font-size:0.8rem;opacity:0.7;">"Ninguna ruta coincidió" → res.status(404)</span></div></div><div class="flujo-paso flujo-pendiente" onclick="avanzarOrdenError(3)"><span class="flujo-num">4</span><div><strong>Middleware de error (4 params)</strong><br><span style="font-size:0.8rem;opacity:0.7;">Captura errores de las rutas → res.status(500)</span></div></div></div>` },
      { nombre: "try/catch + next(error)", contenido: `<p class="mb-6">En rutas asíncronas (<code>async</code>), Express no captura errores automáticamente. Necesitas <code>try/catch</code> y pasarle el error a <code>next()</code>:</p><pre class="bloque-codigo"><code>app.<span class="code-method">get</span>(<span class="code-string">'/usuarios/:id'</span>, <span class="code-keyword">async</span> (req, res, next) => {\n  <span class="code-keyword">try</span> {\n    <span class="code-comment">// Si esto falla (ej: la base de datos está caída)</span>\n    <span class="code-keyword">const</span> usuario = <span class="code-keyword">await</span> <span class="code-method">buscarUsuario</span>(req.params.id);\n    res.<span class="code-method">json</span>(usuario);\n  } <span class="code-keyword">catch</span> (error) {\n    <span class="code-comment">// next(error) salta directo al middleware de error</span>\n    <span class="code-method">next</span>(error);\n  }\n});</code></pre><table class="mt-4"><thead><tr><th>Sin next(error)</th><th>Con next(error)</th></tr></thead><tbody><tr><td>El error se pierde en silencio</td><td>El middleware de error lo captura</td></tr><tr><td>El cliente se queda esperando</td><td>El cliente recibe un mensaje de error</td></tr></tbody></table>` },
      { nombre: "Predice la salida", contenido: `<div class="ejercicio-contenedor" style="background:none;backdrop-filter:none;border:none;box-shadow:none;padding:0;"><pre class="bloque-codigo mb-4"><code><span class="code-comment">// El middleware de error está ANTES de la ruta</span>\napp.<span class="code-method">use</span>((err, req, res, next) => {\n  res.<span class="code-method">status</span>(<span class="code-number">500</span>).<span class="code-method">json</span>({ error: <span class="code-string">'Error personalizado'</span> });\n});\n\napp.<span class="code-method">get</span>(<span class="code-string">'/usuarios'</span>, <span class="code-keyword">async</span> (req, res, next) => {\n  <span class="code-keyword">try</span> {\n    <span class="code-keyword">throw new</span> <span class="code-method">Error</span>(<span class="code-string">'Falla en la base de datos'</span>);\n  } <span class="code-keyword">catch</span> (error) {\n    <span class="code-method">next</span>(error);\n  }\n});</code></pre><p class="ejercicio-pregunta">Un cliente visita /usuarios y ocurre el error. ¿Qué pasa?</p><div class="ejercicio-opciones" data-correcta="1" data-retro-id="cm-errexpress-retro" data-retro-correcta="Exacto: Express procesa de arriba hacia abajo. Como tu middleware de error está antes de la ruta, no llega a registrarse a tiempo para capturar ese error. Express usa su manejador de errores por defecto en su lugar (una respuesta 500 genérica, sin tu formato personalizado)." data-retro-incorrecta="Recuerda: Express procesa de arriba hacia abajo, y un middleware de error solo captura errores de las rutas que vienen DESPUÉS de él, no antes."><button class="ejercicio-opcion" data-opcion="0" onclick="casoMultipleClick(this)"><span class="opcion-icono"></span><span>Tu middleware personalizado lo captura igual, sin importar el orden</span></button><button class="ejercicio-opcion" data-opcion="1" onclick="casoMultipleClick(this)"><span class="opcion-icono"></span><span>No lo captura; Express usa su manejador de errores por defecto en su lugar</span></button><button class="ejercicio-opcion" data-opcion="2" onclick="casoMultipleClick(this)"><span class="opcion-icono"></span><span>El servidor completo deja de funcionar</span></button><button class="ejercicio-opcion" data-opcion="3" onclick="casoMultipleClick(this)"><span class="opcion-icono"></span><span>La petición se queda esperando para siempre</span></button></div><div id="cm-errexpress-retro" class="mt-4"></div></div>` },
    ],
    ejercicio: { tipo: "opcion_multiple", pregunta: "¿Por qué el middleware de error debe ir al final del archivo?", opciones: ["Porque es más lento que los demás", "Porque Express procesa de arriba hacia abajo, y solo puede capturar errores de lo que ya pasó", "Porque solo funciona con POST", "No importa dónde se ponga"], respuestaCorrecta: 1, retroalimentacion: { correcta: "Exacto: Express procesa la pila de arriba hacia abajo. Si el middleware de error está antes de una ruta, no podrá capturar los errores que ocurran en ella.", incorrecta: "Piensa en el orden: Express lee el archivo de arriba hacia abajo. ¿Puede capturar un error de algo que todavía no ha procesado?" } }
  },

  // === FASE 3-7: Partials, layouts y helpers ===
  {
    fase: 3, titulo: "Partials, layouts y helpers", menuTitulo: "Partials y layouts",
    capas: [
      { nombre: "Tres piezas para no repetir código", contenido: `<p class="mb-6">Ya sabes renderizar una vista con EJS. Ahora, tres herramientas para no repetir HTML entre páginas. Toca cada una:</p><div style="display:flex;justify-content:center;gap:0.5rem;margin-bottom:1rem;flex-wrap:wrap;"><button class="motor-btn simbolo-inactivo" data-plantilla="partial" onclick="mostrarPlantilla('partial')">Partial</button><button class="motor-btn simbolo-inactivo" data-plantilla="layout" onclick="mostrarPlantilla('layout')">Layout</button><button class="motor-btn simbolo-inactivo" data-plantilla="helper" onclick="mostrarPlantilla('helper')">Helper</button></div><div id="plantilla-desc" style="max-width:30rem;margin:0 auto;min-height:6rem;"></div>` },
      { nombre: "El ejemplo completo con Handlebars", contenido: `<p class="mb-6">Configuración en el servidor:</p><pre class="bloque-codigo"><code><span class="code-keyword">import</span> hbs <span class="code-keyword">from</span> <span class="code-string">'hbs'</span>;\n\n<span class="code-comment">// 1. Carpeta donde viven los partials</span>\nhbs.<span class="code-method">registerPartials</span>(<span class="code-string">'./views/partials'</span>);\n\n<span class="code-comment">// 2. Un helper personalizado</span>\nhbs.<span class="code-method">registerHelper</span>(<span class="code-string">'enMayusculas'</span>, (texto) => {\n  <span class="code-keyword">return</span> texto.<span class="code-method">toUpperCase</span>();\n});\n\napp.<span class="code-method">set</span>(<span class="code-string">'view engine'</span>, <span class="code-string">'hbs'</span>);</code></pre><p class="mt-4 mb-2">En la vista (<code>index.hbs</code>):</p><pre class="bloque-codigo"><code><span class="code-comment">&lt;!-- Invoca un partial --&gt;</span>\n{{<span class="code-method">> header</span>}}\n\n{{<span class="code-keyword">#each</span> desarrolladores}}\n  <span class="code-comment">&lt;!-- {{this}} = elemento actual del arreglo --&gt;</span>\n  &lt;li&gt;{{<span class="code-method">enMayusculas this</span>}}&lt;/li&gt;\n{{<span class="code-keyword">/each</span>}}\n\n{{<span class="code-method">> footer</span>}}</code></pre>` },
      { nombre: "Clasifícalos", contenido: `<p class="ejercicio-pregunta mb-2" style="text-align:center;">Cada elemento de abajo es un uso real de una de estas tres herramientas.</p><p class="mb-6" style="text-align:center;font-size:0.85rem;opacity:0.7;">Arrastra cada uno a su categoría correcta:</p><div class="categ-wrap" data-contenedor="plantillas"><div class="categ-pool" ondragover="categDragOver(event)" ondrop="categDrop(event)"><div class="categ-item" draggable="true" data-categoria="partial" ondragstart="categDragStart(event)" ondragend="categDragEnd(event)"><code>{{> nav}}</code></div><div class="categ-item" draggable="true" data-categoria="layout" ondragstart="categDragStart(event)" ondragend="categDragEnd(event)"><code>&lt;html&gt;...&lt;head&gt;...&lt;/html&gt;</code></div><div class="categ-item" draggable="true" data-categoria="helper" ondragstart="categDragStart(event)" ondragend="categDragEnd(event)"><code>{{enMayusculas texto}}</code></div><div class="categ-item" draggable="true" data-categoria="partial" ondragstart="categDragStart(event)" ondragend="categDragEnd(event)"><code>{{> footer}}</code></div><div class="categ-item" draggable="true" data-categoria="helper" ondragstart="categDragStart(event)" ondragend="categDragEnd(event)"><code>registerHelper()</code></div></div><div class="categ-cajas"><div class="categ-caja" data-categoria="partial" ondragover="categDragOver(event)" ondrop="categDrop(event)"><div class="categ-caja-titulo">Partial</div><div class="categ-caja-lista"></div></div><div class="categ-caja" data-categoria="layout" ondragover="categDragOver(event)" ondrop="categDrop(event)"><div class="categ-caja-titulo">Layout</div><div class="categ-caja-lista"></div></div><div class="categ-caja" data-categoria="helper" ondragover="categDragOver(event)" ondrop="categDrop(event)"><div class="categ-caja-titulo">Helper</div><div class="categ-caja-lista"></div></div></div></div><div style="text-align:center;margin-top:1.5rem;"><button class="motor-btn" onclick="comprobarCategorias('plantillas')">Comprobar respuesta</button></div><div id="categ-plantillas-retro" class="mt-4" style="min-height:3rem;"></div>` },
    ],
    ejercicio: { tipo: "opcion_multiple", pregunta: "Tienes 15 páginas que necesitan el mismo <head> con los mismos enlaces a CSS. ¿Qué herramienta evita repetir ese código 15 veces?", opciones: ["Un partial", "Un layout", "Un helper", "Un middleware"], respuestaCorrecta: 1, retroalimentacion: { correcta: "Exacto: el layout define la estructura base (head, body) una sola vez, y cada vista se inyecta dentro de él.", incorrecta: "Piensa: un partial reutiliza un fragmento (como un header), pero lo que describes es la estructura completa del documento. ¿Qué herramienta define eso una sola vez para todas las páginas?" } }
  },

  // === FASE 3-8: Validación con Joi ===
  {
    fase: 3, titulo: "Validación de datos con Joi", menuTitulo: "Validación con Joi",
    capas: [
      { nombre: "¿Por qué validar?", contenido: `<p class="mb-6">Tu servidor puede recibir <strong>cualquier cosa</strong> en <code>req.body</code>: campos vacíos, formatos incorrectos, o datos que nunca debieron llegar. <strong>Joi</strong> es una librería que valida esos datos antes de que toquen tu lógica de negocio o tu base de datos.</p><table><thead><tr><th>Sin validar</th><th>Con Joi</th></tr></thead><tbody><tr><td>Un email mal escrito llega a la base de datos</td><td>Se rechaza con 400 antes de guardarse</td></tr><tr><td>Un campo obligatorio llega vacío</td><td>Joi detecta el vacío y detiene el flujo</td></tr><tr><td>El cliente envía campos extra no autorizados</td><td>El schema define exactamente qué se acepta</td></tr></tbody></table>` },
      { nombre: "Probar el schema", contenido: `<p class="mb-6">Este es el schema de validación para un registro de usuario:</p><pre class="bloque-codigo"><code><span class="code-keyword">const</span> schema = Joi.<span class="code-method">object</span>({\n  nombre: Joi.<span class="code-method">string</span>().<span class="code-method">min</span>(<span class="code-number">2</span>).<span class="code-method">required</span>(),\n  email: Joi.<span class="code-method">string</span>().<span class="code-method">email</span>().<span class="code-method">required</span>(),\n  edad: Joi.<span class="code-method">number</span>().<span class="code-method">integer</span>().<span class="code-method">min</span>(<span class="code-number">18</span>).<span class="code-method">required</span>()\n});</code></pre><p class="mb-4">Toca cada envío para ver si pasa la validación:</p><div style="display:flex;flex-direction:column;gap:0.5rem;max-width:30rem;margin:0 auto;"><button class="motor-btn simbolo-inactivo" style="text-align:left;" onclick="probarJoi(0)">{ nombre: "Ana", email: "ana@mail.com", edad: 25 }</button><button class="motor-btn simbolo-inactivo" style="text-align:left;" onclick="probarJoi(1)">{ nombre: "Ana", email: "no-es-email", edad: 25 }</button><button class="motor-btn simbolo-inactivo" style="text-align:left;" onclick="probarJoi(2)">{ nombre: "Ana", email: "ana@mail.com", edad: 15 }</button></div><div id="joi-resultado" class="mt-4"></div>` },
      { nombre: "Escríbelo tú", contenido: `<p class="ejercicio-pregunta mb-2" style="text-align:center;">Estás agregando el campo "precio" a un schema de productos. Debe ser un número, obligatorio, y no puede ser negativo.</p><p class="mb-6" style="text-align:center;font-size:0.85rem;opacity:0.7;">Completa la línea del schema:</p><div class="ccb-wrap" data-contenedor="joi" data-respuesta="Joi.number().min(0).required()|Joi.number().positive().required()" data-salida="ValidationError: precio es requerido" data-retro-correcta="Exacto: number() valida que sea un número, min(0) o positive() evita valores negativos, y required() lo hace obligatorio." data-retro-incorrecta="Piensa en 3 reglas por separado: qué tipo de dato es, que no pueda ser negativo, y que sea obligatorio. Cada una es un método encadenado."><pre class="bloque-codigo"><code><span class="code-keyword">const</span> schema = Joi.<span class="code-method">object</span>({\n  nombre: Joi.<span class="code-method">string</span>().<span class="code-method">required</span>(),\n  precio: <input type="text" class="ccb-input" id="ccb-joi-input" placeholder="?" autocomplete="off" spellcheck="false" onkeydown="ccbEnter(event,'joi')" style="width:16rem;">\n});</code></pre><div class="consola-simulada mt-3"><div class="consola-header">Al enviar { nombre: "Mesa", precio: undefined }</div><div class="ccb-consola-salida"><span style="opacity:0.4;">Esperando...</span></div></div><div style="text-align:center;margin-top:1.25rem;"><button class="motor-btn" onclick="comprobarCCB('joi')">Comprobar</button></div><div id="ccb-joi-retro" class="mt-4" style="min-height:3rem;"></div></div>` },
    ],
    ejercicio: { tipo: "opcion_multiple", pregunta: "Un cliente envía { nombre: 'A', email: 'x@mail.com', edad: 30 } al schema visto arriba. ¿Qué pasa?", opciones: ["Pasa la validación sin problema", "Falla porque 'nombre' no cumple el mínimo de 2 caracteres", "Falla porque falta un campo", "Falla porque edad debe ser string"], respuestaCorrecta: 1, retroalimentacion: { correcta: "Exacto: el schema pide .min(2) para nombre, y 'A' tiene solo 1 carácter. Joi lo rechaza con un error 400.", incorrecta: "Revisa la regla del campo nombre: Joi.string().min(2). ¿Cuántos caracteres tiene 'A'?" } }
  },

  // === FASE 3-9: Consumir APIs externas con axios ===
  {
    fase: 3, titulo: "Consumir APIs externas con axios", menuTitulo: "Axios",
    capas: [
      { nombre: "¿Qué es axios?", contenido: `<p class="mb-6"><strong>axios</strong> es una librería para hacer peticiones HTTP desde tu código. Se usa cuando tu propio servidor necesita datos de <strong>otra API</strong> (un servicio de clima, una pasarela de pago, otro microservicio) antes de responderle a su propio cliente.</p><div style="display:flex;justify-content:center;align-items:center;gap:0.75rem;margin:1.5rem 0;flex-wrap:wrap;"><div style="background:rgba(91,139,212,.35);backdrop-filter:blur(8px);border:1px solid rgba(91,139,212,.5);color:#1d3f6e;padding:0.5rem 1rem;border-radius:0.5rem;font-size:0.85rem;">Cliente</div><span style="opacity:0.4;">→</span><div style="background:rgba(51,153,51,.35);backdrop-filter:blur(8px);border:1px solid rgba(51,153,51,.5);color:#1a4d1a;padding:0.5rem 1rem;border-radius:0.5rem;font-size:0.85rem;">Tu servidor</div><span style="opacity:0.4;">→ axios →</span><div style="background:rgba(230,185,128,.4);backdrop-filter:blur(8px);border:1px solid rgba(230,185,128,.55);color:#7A5B00;padding:0.5rem 1rem;border-radius:0.5rem;font-size:0.85rem;">API externa</div></div>` },
      { nombre: "axios vs fetch", contenido: `<p class="mb-6">Node ya tiene <code>fetch</code> nativo. Toca cada uno para ver por qué axios se prefiere en producción:</p><div style="display:flex;justify-content:center;gap:1rem;margin-bottom:1rem;"><button id="btn-fetch" class="motor-btn simbolo-inactivo" onclick="compararAxios('fetch')">fetch</button><button id="btn-axios" class="motor-btn simbolo-inactivo" onclick="compararAxios('axios')">axios</button></div><pre class="bloque-codigo"><code id="axios-codigo" style="min-height:6rem;"><span class="code-comment">// Elige una opción arriba</span></code></pre>` },
      { nombre: "Ruta completa con manejo de errores", contenido: `<pre class="bloque-codigo"><code>app.<span class="code-method">get</span>(<span class="code-string">'/api/clima/:ciudad'</span>, <span class="code-keyword">async</span> (req, res) => {\n  <span class="code-keyword">const</span> { ciudad } = req.params;\n  <span class="code-keyword">try</span> {\n    <span class="code-keyword">const</span> response = <span class="code-keyword">await</span> axios.<span class="code-method">get</span>(\n      <span class="code-string">\`https://api-clima.com/pronostico?q=\${ciudad}\`</span>,\n      { timeout: <span class="code-number">4000</span> }  <span class="code-comment">// aborta si tarda más de 4s</span>\n    );\n    res.<span class="code-method">json</span>({ temperatura: response.data.temperatura_actual });\n  } <span class="code-keyword">catch</span> (error) {\n    <span class="code-keyword">if</span> (error.response) {\n      <span class="code-comment">// La API externa respondió, pero con error (404, 500...)</span>\n      res.<span class="code-method">status</span>(error.response.status).<span class="code-method">json</span>({ error: <span class="code-string">'La API externa falló'</span> });\n    } <span class="code-keyword">else if</span> (error.request) {\n      <span class="code-comment">// La API externa nunca respondió (caída o timeout)</span>\n      res.<span class="code-method">status</span>(<span class="code-number">504</span>).<span class="code-method">json</span>({ error: <span class="code-string">'Sin respuesta de la API externa'</span> });\n    }\n  }\n});</code></pre><table class="mt-4"><thead><tr><th>Caso</th><th>Objeto de error</th></tr></thead><tbody><tr><td>La API externa respondió con error</td><td><code>error.response</code></td></tr><tr><td>La API externa nunca respondió</td><td><code>error.request</code></td></tr></tbody></table>` },
      { nombre: "Ponlo en práctica", contenido: `<div class="ejercicio-contenedor" style="background:none;backdrop-filter:none;border:none;box-shadow:none;padding:0;"><div class="recuadro-resaltado mb-4" style="text-align:justify;">Tu API depende de un servicio externo de pagos. Durante una prueba, ese servicio está completamente caído: el servidor no responde absolutamente nada, ni siquiera un código de error HTTP.</div><p class="ejercicio-pregunta">Dentro del catch, ¿qué deberías revisar para detectar específicamente este caso?</p><div class="ejercicio-opciones" data-correcta="1" data-retro-id="cm-axios-retro" data-retro-correcta="Exacto: error.request existe cuando axios sí llegó a enviar la petición, pero nunca recibió ninguna respuesta (servicio caído, timeout, sin conexión)." data-retro-incorrecta="Recuerda la diferencia: error.response existe cuando la API SÍ respondió (aunque con error). Si el servicio está completamente caído, la API nunca respondió."><button class="ejercicio-opcion" data-opcion="0" onclick="casoMultipleClick(this)"><span class="opcion-icono"></span><span>error.response</span></button><button class="ejercicio-opcion" data-opcion="1" onclick="casoMultipleClick(this)"><span class="opcion-icono"></span><span>error.request</span></button><button class="ejercicio-opcion" data-opcion="2" onclick="casoMultipleClick(this)"><span class="opcion-icono"></span><span>error.message únicamente</span></button><button class="ejercicio-opcion" data-opcion="3" onclick="casoMultipleClick(this)"><span class="opcion-icono"></span><span>No hay forma de distinguir este caso</span></button></div><div id="cm-axios-retro" class="mt-4"></div></div>` },
    ],
    ejercicio: { tipo: "opcion_multiple", pregunta: "Usas axios.get() para consultar una API externa, y esa API responde con un 404. ¿Qué pasa con la promesa de axios?", opciones: ["Se resuelve con éxito, hay que revisar response.ok manualmente", "Se rechaza automáticamente y cae en el catch", "axios ignora el error y sigue esperando", "Node lanza una excepción no capturable"], respuestaCorrecta: 1, retroalimentacion: { correcta: "Exacto: a diferencia de fetch, axios rechaza automáticamente la promesa ante cualquier código fuera del rango 2xx, así que cae directo al catch.", incorrecta: "Esa es la forma en que se comporta fetch (hay que revisar response.ok a mano). axios se comporta distinto: ¿qué hace automáticamente ante un código de error?" } }
  },

];
